import{_ as t,o as a,c as s,a3 as o}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"Referencing values","description":"What an ApptiveScript expression starts with — field values, form input, step results.","frontmatter":{"title":"Referencing values","description":"What an ApptiveScript expression starts with — field values, form input, step results."},"headers":[],"relativePath":"en/apptivescript/werte-referenzieren.md","filePath":"en/apptivescript/werte-referenzieren.md","lastUpdated":1787319236000}'),n={name:"en/apptivescript/werte-referenzieren.md"};function i(r,e,d,l,c,p){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="referencing-values" tabindex="-1">Referencing values <a class="header-anchor" href="#referencing-values" aria-label="Permalink to &quot;Referencing values&quot;">​</a></h1><p>The syntax is the same everywhere. What differs is the <strong>starting point</strong> — the first value an expression begins with. It depends on where you&#39;re writing.</p><table tabindex="0"><thead><tr><th>Starting point</th><th>Represents</th><th>Available in</th></tr></thead><tbody><tr><td><code>fieldValue(&#39;&lt;field id&gt;&#39;)</code></td><td>a field of the current entry</td><td>Formula columns, filters</td></tr><tr><td><code>formValues.get(&#39;&lt;key&gt;&#39;)</code></td><td>an input on a page</td><td>conditional visibility</td></tr><tr><td><code>step(&#39;&lt;step id&gt;&#39;)</code></td><td>an earlier step of a Flow</td><td>Flows</td></tr><tr><td><code>today()</code> · <code>now()</code></td><td>today&#39;s date · the current moment</td><td>everywhere</td></tr><tr><td><code>true</code> · <code>false</code></td><td>fixed boolean values</td><td>everywhere</td></tr><tr><td><code>loggedInUser()</code></td><td>the signed-in person</td><td>everywhere</td></tr><tr><td><code>owner</code></td><td>the Space&#39;s owner</td><td>Flows</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">The most common mistake is in this table</p><p>A starting point that doesn&#39;t exist at that spot doesn&#39;t produce <strong>an error</strong> — it produces an empty result. <code>fieldValue(&#39;…&#39;)</code> in a visibility rule stays silently ineffective, and the block disappears permanently. Check the starting point first, then the function.</p></div><h2 id="fields-of-an-entry-fieldvalue" tabindex="-1">Fields of an entry: <code>fieldValue</code> <a class="header-anchor" href="#fields-of-an-entry-fieldvalue" aria-label="Permalink to &quot;Fields of an entry: `fieldValue`&quot;">​</a></h2><p>In a <strong>Formula column</strong> and in <strong>filters</strong>, you access the other fields of the same entry:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fieldValue(&#39;64f2a1c0b53ff00c6bdf1234&#39;).multiplyBy(1.19)</span></span></code></pre></div><p>The value in the parentheses is the column&#39;s <strong>id</strong>, not its name.</p><div class="tip custom-block"><p class="custom-block-title">Never type it, always insert it</p><p>In the formula editor, the <strong>Search</strong> tab lists all usable fields by name. A click inserts <code>fieldValue(&#39;…&#39;)</code> with the correct id and displays it as a colored block showing the field name. That way, the expression shows you the name, while the id is what actually gets stored.</p></div><p>Storing the id has an upside: <strong>a formula survives the column being renamed.</strong> And a downside: if the column is deleted, the editor reports <em>No field with id …</em> — the field name no longer appears in the expression.</p><p><strong>Which fields can be used:</strong> Text, Number, Decimal, Currency, Date, Date and time, Created at, Checkmark, User, E-Mail, and Geolocation. Other column types don&#39;t show up in the picker.</p><div class="warning custom-block"><p class="custom-block-title">Formula columns can&#39;t reference other formula columns</p><p>Fields of type <em>Formula</em> are left out of the picker — otherwise a formula could end up trying to calculate itself. If you need to build on a computed value, repeat the calculation in the new expression.</p></div><h2 id="inputs-on-a-page-formvalues" tabindex="-1">Inputs on a page: <code>formValues</code> <a class="header-anchor" href="#inputs-on-a-page-formvalues" aria-label="Permalink to &quot;Inputs on a page: `formValues`&quot;">​</a></h2><p>In a block&#39;s <a href="/en/seiten/sichtbarkeit">conditional visibility</a>, the values come from the input blocks on the same page:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>formValues.get(&#39;age&#39;).greaterThan(17)</span></span></code></pre></div><p>Access happens via the input block&#39;s <strong>Key</strong> — not its label. You can see all Keys on a page via <strong>Manage Keys</strong>. → <a href="/en/seiten/eingabebloecke">Input blocks</a></p><div class="danger custom-block"><p class="custom-block-title">A wrong Key hides the block permanently</p><p>If the Key is <code>age</code> and the rule asks for <code>formValues.get(&#39;alter&#39;)</code>, the condition is <strong>always false</strong> — the block never appears, without any message. The same thing happens if the Key is changed later.</p><p>Settle on meaningful Keys <strong>before</strong> you build conditions on top of them.</p></div><p>There&#39;s a special case with the opposite outcome: if the expression isn&#39;t just pointing at nothing, but is <strong>syntactically wrong</strong>, the block stays visible. So a block that always appears points to a typo; a block that never appears points to a wrong Key.</p><h2 id="results-of-earlier-steps-step" tabindex="-1">Results of earlier steps: <code>step</code> <a class="header-anchor" href="#results-of-earlier-steps-step" aria-label="Permalink to &quot;Results of earlier steps: `step`&quot;">​</a></h2><p>In a <a href="/en/flows/was-ist-ein-flow">Flow</a>, every step produces a result that later steps can access:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>step(&#39;66f13d06b53ff00c6bdf2769&#39;).output.get(&#39;email&#39;)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Part</th><th>Meaning</th></tr></thead><tbody><tr><td><code>step(&#39;…&#39;)</code></td><td>the step, identified by its id</td></tr><tr><td><code>.output</code></td><td>the result of that step</td></tr><tr><td><code>.get(&#39;…&#39;)</code></td><td>a single field from it</td></tr></tbody></table><p>Here too, nobody types ids by hand: the <strong>Flow</strong> tab in the expression editor shows the Flow&#39;s steps as a tree, and a click inserts the matching expression. The tree is built from the <strong>last test run</strong> — without a test run it&#39;s empty, and the editor says so:</p><blockquote><p><em>You need to test the Flow first</em></p></blockquote><p>→ <a href="/en/flows/testen">Testing Flows</a> · <a href="/en/flows/daten-zwischen-schritten">Passing data between steps</a></p><div class="tip custom-block"><p class="custom-block-title">Nested data with multiple <code>get</code>s</p><p>Webhook data and JSON responses are often nested. In that case, chain <code>get()</code> calls: <code>step(&#39;…&#39;).output.get(&#39;customer&#39;).get(&#39;email&#39;)</code>. Each <code>get()</code> goes one level deeper.</p></div><h2 id="date-person-space" tabindex="-1">Date, person, Space <a class="header-anchor" href="#date-person-space" aria-label="Permalink to &quot;Date, person, Space&quot;">​</a></h2><p>These starting points don&#39;t need any connection to an entry or a step:</p><table tabindex="0"><thead><tr><th>Expression</th><th>Result</th></tr></thead><tbody><tr><td><code>today()</code></td><td>today&#39;s date, without a time</td></tr><tr><td><code>now()</code></td><td>the current moment, with a time</td></tr><tr><td><code>loggedInUser()</code></td><td>the signed-in person, with <code>.email</code>, <code>.firstName</code>, <code>.lastName</code>, <code>.id</code></td></tr><tr><td><code>owner</code></td><td>the Space&#39;s owner, with <code>.email</code>, <code>.firstName</code>, <code>.lastName</code></td></tr><tr><td><code>true</code> · <code>false</code></td><td>fixed boolean values</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fieldValue(&#39;deadline&#39;).before(today())</span></span>\n<span class="line"><span>loggedInUser().email.isEqualTo(fieldValue(&#39;assignee&#39;))</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title"><code>owner</code> is only offered by the interface in Flows</p><p>The three values <em>Space owner email</em>, <em>Space owner first name</em>, and <em>Space owner last name</em> are available in the expression editor as <strong>Flow variables</strong>. For formulas and visibility rules, the interface doesn&#39;t offer them — don&#39;t rely on them there.</p></div><div class="tip custom-block"><p class="custom-block-title">Who&#39;s signed in during a Flow?</p><p><code>loggedInUser()</code> is the person who triggered the action. If a Flow runs via a <a href="/en/flows/webhook-trigger">webhook</a> or a public form, that&#39;s not necessarily a member of the Space. For attribution, an explicitly filled-in field is more reliable than the signed-in user.</p></div><h2 id="which-type-comes-out" tabindex="-1">Which type comes out <a class="header-anchor" href="#which-type-comes-out" aria-label="Permalink to &quot;Which type comes out&quot;">​</a></h2><p>In a <strong>Formula column</strong>, you choose the result&#39;s column type under <em>Display result as</em>. The options depend on the type the expression returns:</p><table tabindex="0"><thead><tr><th>Expression returns</th><th>Selectable column types</th></tr></thead><tbody><tr><td>Boolean</td><td>Checkmark</td></tr><tr><td>Number</td><td>Number, Decimal, Currency</td></tr><tr><td>Decimal</td><td>Decimal, Currency</td></tr><tr><td>Text</td><td>Text</td></tr><tr><td>Date</td><td>Date</td></tr><tr><td>Date and time</td><td>Date and time</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Why the selection sometimes shrinks to one entry</p><p>If only one column type is left, the editor sets it for you — the expression doesn&#39;t allow anything else. Conversely, a suddenly long list means the expression can&#39;t be evaluated yet, and the type isn&#39;t determined yet.</p></div><p>Which type an expression is currently returning is shown in the editor above the sample result — <em>Type: String</em>, <em>Type: Number</em>. It also determines which functions are possible next. → <a href="/en/referenz/apptivescript-funktionen">Function reference</a></p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/apptivescript/schreibweise">Syntax</a> — dots, parentheses, quotation marks</li><li><a href="/en/apptivescript/bedingungen">Building conditions</a> — comparisons, AND/OR, branches</li><li><a href="/en/apptivescript/editor">The expression editor</a> — token view, picker, sample result</li><li><a href="/en/referenz/apptivescript-funktionen">Function reference</a> — every function by type</li><li><a href="/en/grids/berechnete-felder">Computed fields</a> · <a href="/en/seiten/sichtbarkeit">Conditional visibility</a> · <a href="/en/seiten/eingabebloecke">Input blocks</a></li></ul>',39)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
